WITH customer_volume AS (
    SELECT CustomerID, SUM(Amount) AS total_volume
    FROM transactions_1k
    GROUP BY CustomerID
), max_volume AS (
    SELECT MAX(total_volume) AS max_total FROM customer_volume
)
SELECT CustomerID
FROM customer_volume
WHERE total_volume = (SELECT max_total FROM max_volume);

